namespace SentinelRemoteAssist;

/// <summary>
/// Regenerated by the bastion builder's /build-installer endpoint before every auto-provisioning
/// build — bakes the account-bound enrollment ticket + server URL + ToS version directly into the
/// binary, so the finished .exe is the ONLY file that needs to go to the target PC. A double-click
/// then: shows the ToS/MSA (fetched live from the server, versioned), elevates, installs with
/// persistence, and enrolls the device with this single-use multi-allow ticket — no login on the
/// target PC (see AutoProvisionFlow.cs). This file (AutoProvisionEmbedded.cs, gitignored — this
/// .template copy is the tracked placeholder) holds a live enrollment ticket once generated.
/// NEVER commit the real generated copy.
/// </summary>
internal static class AutoProvisionEmbedded
{
    /// <summary>Server base URL (https://app.example.com) the agent talks to.</summary>
    public const string WebUrl = "";
    /// <summary>Multi-use, bind-any-device enrollment ticket minted for the owning account —
    /// consumed by the device's first socket handshake (see RemoteAssistSocket.BuildAuthPayload).</summary>
    public const string EnrollmentTicket = "";
    /// <summary>ToS/MSA version the ticket was minted against (agent shows + records acceptance
    /// of exactly this version; the server rejects consent for a mismatched version).</summary>
    public const string TosVersion = "";

    public static bool IsConfigured => !string.IsNullOrEmpty(EnrollmentTicket);
}
